-- Rencana aksi disamakan dengan Formulir Rencana Tindakan Peningkatan Berkelanjutan (klausul 6.2, 003/SOP-008/KINRA/SMEn/X/2026, Rev.0 (Net)),
-- tabel peluang/proyek yang dipilih. Angka estimasi mengikuti formulir apa adanya, termasuk LED 443 unit (164.790 kWh/tahun).
-- Catatan formulir: nomor 1 (LED) dan 5 (penerangan jalan) memakai angka penghematan yang sama dan perlu dikonsolidasikan
-- agar tidak dihitung dua kali; keterangan itu disimpan di kolom catatan.
-- 1) Rencana aksi buatan aplikasi (semua yang tidak bersumber dari formulir, migrasi 0039/0041 dan isian manual) dihapus.
--    Tautan deviasi ke aksi yang terhapus dikosongkan.
-- 2) Tindakan dari formulir dimuat dengan kode RT-01 dst. Status 'Rencana', karena formulir belum mencantumkan jadwal dan status.
-- Jalankan setelah 0049. Aman diulang.

alter table rencana_aksi add column if not exists deskripsi text;
alter table rencana_aksi add column if not exists seu_terkait text;
alter table rencana_aksi add column if not exists sasaran_teks text;
alter table rencana_aksi add column if not exists tanggal_identifikasi date;
alter table rencana_aksi add column if not exists sumber text;

delete from rencana_aksi where sumber is null;
delete from rencana_aksi where sumber like 'Formulir Rencana Tindakan 6.2%';

insert into rencana_aksi (kode, uraian, deskripsi, seu_terkait, sasaran_teks, pic, tanggal_identifikasi, estimasi_hemat_kwh, status, catatan, sumber)
values
('RT-01', 'Penggantian lampu menjadi LED efisiensi tinggi', 'Melaksanakan penggantian lampu konvensional jenis Mercury 250 Watt menjadi LED 150 Watt pada penerangan jalan kawasan. Mengganti lampu Graha dari 20 Watt menjadi LED 18 Watt. Pelaksanaan mempertimbangkan tingkat pencahayaan, keselamatan, dan kebutuhan operasional.', 'Ya – Pencahayaan gedung dan kawasan', 'Penurunan konsumsi energi listrik untuk pencahayaan melalui penggunaan teknologi lampu hemat energi.', 'Manager Energi', '2026-10-29', 164790, 'Rencana', 'Penggantian 443 unit lampu Mercury 250 Watt menjadi LED 150 Watt dan 47 unit lampu Graha 20 Watt menjadi LED 18 Watt dari total 126 unit. Penghematan diverifikasi melalui perbandingan daya terpasang, jam operasi, dan konsumsi aktual sebelum dan sesudah penggantian.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 1'),
('RT-02', 'Pengaturan jadwal dan zonasi pencahayaan', 'Menerapkan pengaturan waktu operasional lampu jalan menggunakan timer otomatis untuk mengendalikan penyalaan dan pemadaman lampu. Melakukan pengaturan zonasi berdasarkan kebutuhan penerangan, jam operasional, aktivitas kawasan, serta kondisi keamanan.', 'Ya – Pencahayaan gedung dan kawasan', 'Pengurangan konsumsi listrik melalui pengendalian jam operasional dan optimalisasi penggunaan penerangan.', 'Manager Energi', '2026-10-29', 180000, 'Rencana', 'Menggunakan timer otomatis dengan pengaturan lampu menyala selama 12 jam dan mati selama 12 jam. Melakukan pemeriksaan berkala terhadap fungsi timer, jadwal operasional, dan kondisi lampu. Penghematan dihitung berdasarkan pengurangan jam operasi dan daya lampu.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 2'),
('RT-03', 'Pemasangan submeter dan pemantauan energi melalui SCADA berbasis IoT', 'Memasang dan mengintegrasikan submeter pada panel distribusi, gedung, fasilitas, dan peralatan dengan konsumsi energi signifikan. Mengembangkan sistem pemantauan berbasis SCADA dan IoT untuk menampilkan data konsumsi secara berkala, mendeteksi anomali, serta menyediakan informasi sebagai dasar analisis peluang penghematan energi.', 'Ya – Sistem pengukuran dan pemantauan energi serta SEU yang dipantau', 'Peningkatan akurasi pengukuran, pengendalian konsumsi energi, dan identifikasi potensi penghematan pada setiap area operasional.', 'Manager Energi', '2026-10-29', null, 'Rencana', 'Penghematan belum dihitung karena saat ini masih daalam progress dan kegiatan merupakan peningkatan sistem pengukuran dan pemantauan. Melakukan inventarisasi titik pengukuran, pemasangan submeter, integrasi komunikasi data, penyusunan dashboard, dan evaluasi tren konsumsi energi. Indikator keberhasilan: ketersediaan data, akurasi pengukuran, dan jumlah anomali yang ditindaklanjuti.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 3'),
('RT-04', 'Efisiensi energi peralatan kantor', 'Mengoptimalkan penggunaan energi pada komputer, printer, AC, perangkat jaringan, dispenser, dan peralatan administrasi lainnya melalui pengaturan mode hemat energi, pengaturan suhu AC, pemadaman peralatan setelah jam kerja, serta penerapan instruksi kerja hemat energi.', 'Ya – Peralatan administrasi, apabila hasil evaluasi menunjukkan penggunaan energi signifikan', 'Penurunan konsumsi listrik peralatan administrasi dan fasilitas kantor melalui pengendalian penggunaan serta peningkatan efisiensi operasional.', 'Steering Committee / MR', '2026-10-29', null, 'Rencana', 'Melakukan inventarisasi peralatan listrik kantor, menetapkan jadwal operasional, mengaktifkan fitur sleep mode, dan memastikan peralatan tidak beroperasi tanpa kebutuhan. Penghematan akan dihitung setelah tersedia data baseline konsumsi dan hasil pemantauan submeter.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 4'),
('RT-05', 'Efisiensi energi penerangan jalan dan fasilitas luar ruang', 'Melakukan evaluasi dan optimalisasi sistem penerangan jalan kawasan, termasuk penggantian lampu Mercury 250 Watt menjadi LED 150 Watt, pemeriksaan tingkat pencahayaan, pengaturan waktu operasional, dan pemeliharaan instalasi penerangan agar konsumsi listrik lebih efisien tanpa mengurangi aspek keselamatan.', 'Ya – Penerangan jalan dan area luar', 'Penurunan konsumsi energi listrik untuk penerangan jalan dan fasilitas luar ruang melalui penggunaan lampu berdaya rendah dan efisien.', 'Manager Energi', '2026-10-29', 164790, 'Rencana', 'Berdasarkan penggantian 443 unit lampu Mercury 250 Watt menjadi LED 150 Watt. Melakukan verifikasi daya lampu, jumlah unit, jam operasi, serta pengukuran konsumsi listrik sebelum dan sesudah program. Angka penghematan ini perlu dikonsolidasikan dengan peluang nomor 1 agar tidak dihitung dua kali.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 5'),
('RT-06', 'Monitoring sistem manajemen energi berbasis web', 'Mengembangkan dan menerapkan sistem monitoring manajemen energi berbasis web yang terintegrasi dengan data konsumsi listrik, produksi energi PLTS, PLTBG, penggunaan BBM, serta hasil pengukuran submeter. Sistem digunakan untuk memantau tren konsumsi, membandingkan realisasi terhadap baseline dan sasaran energi, serta menyediakan laporan kinerja energi secara berkala.', 'Ya – Sistem pengukuran, pemantauan, dan pengendalian energi yang mendukung seluruh SEU', 'Peningkatan efektivitas pemantauan kinerja energi, pengendalian konsumsi, evaluasi sasaran energi, dan identifikasi peluang penghematan secara berkelanjutan.', 'Steering Committee / MR', '2026-10-29', null, 'Rencana', 'Penghematan belum dihitung karena sistem merupakan sarana pendukung pengendalian energi. Mengembangkan dashboard dengan fitur data historis, grafik tren, indikator kinerja energi (EnPI), perbandingan baseline, notifikasi penyimpangan, dan laporan bulanan. Indikator keberhasilan: ketersediaan dashboard, ketepatan data, dan penyelesaian tindak lanjut atas penyimpangan konsumsi energi.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 6'),
('RT-07', 'Pelatihan dan kampanye perilaku hemat energi', 'Melaksanakan program peningkatan kompetensi dan kesadaran personel KINRA, tenant, serta pihak terkait mengenai konservasi energi melalui pelatihan, sosialisasi kebijakan energi, pemasangan media kampanye, instruksi kerja, inspeksi, dan pelaporan perilaku pemborosan energi.', 'Ya – Lintas fasilitas dan proses operasional, khususnya SEU yang dipengaruhi perilaku pengguna', 'Peningkatan kompetensi, kesadaran, dan partisipasi personel dalam mendukung pencapaian sasaran energi dan peningkatan kinerja energi.', 'Steering Committee / MR', '2026-10-29', null, 'Rencana', 'Menyusun program pelatihan berkala, daftar peserta, materi sosialisasi, poster hemat energi, dan checklist inspeksi. Melakukan evaluasi efektivitas melalui hasil pre-test/post-test, kepatuhan terhadap instruksi kerja, temuan pemborosan energi, dan tindak lanjut perbaikan. Penghematan dihitung setelah dampak program dapat diukur.', 'Formulir Rencana Tindakan 6.2 003/SOP-008/KINRA/SMEn/X/2026 · No. 7');

update deviasi set aksi_kode = null where aksi_kode is not null and aksi_kode not in (select kode from rencana_aksi);
